package com.muneebwanee.bookwiz;
import android.app.PendingIntent;
import android.appwidget.*;
import android.content.*;
import android.widget.RemoteViews;
import org.json.JSONObject;
public class BookWidgets extends AppWidgetProvider {
 public static class CurrentBook extends BookWidgets {} public static class DailyGoal extends BookWidgets {} public static class QuickCapture extends BookWidgets {} public static class WritingTime extends BookWidgets {} public static class Bookshelf extends BookWidgets {}
 private String action(){String name=getClass().getSimpleName();return name.equals("DailyGoal")?"goal":name.equals("QuickCapture")?"capture":name.equals("WritingTime")?"session":name.equals("Bookshelf")?"library":"resume";}
 @Override public void onReceive(Context c,Intent intent){super.onReceive(c,intent);if(Intent.ACTION_CONFIGURATION_CHANGED.equals(intent.getAction()))onUpdate(c,AppWidgetManager.getInstance(c),AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,getClass())));}
 @Override public void onUpdate(Context c,AppWidgetManager manager,int[] ids){JSONObject d;try{d=new JSONObject(c.getSharedPreferences("bookwiz-widgets",0).getString("data","{}"));}catch(Exception e){d=new JSONObject();}java.util.Calendar snapshot=java.util.Calendar.getInstance(),now=java.util.Calendar.getInstance();snapshot.setTimeInMillis(d.optLong("snapshotAt",0));boolean sameDay=snapshot.get(java.util.Calendar.YEAR)==now.get(java.util.Calendar.YEAR)&&snapshot.get(java.util.Calendar.DAY_OF_YEAR)==now.get(java.util.Calendar.DAY_OF_YEAR);String a=action(),title="Your writing room",value="Open BookWiz",detail="Your next page is waiting.";
 if(a.equals("goal")){title="Today’s page";value=(sameDay?d.optInt("today",0):0)+" / "+d.optInt("goal",500);detail="Words toward your daily goal";}else if(a.equals("capture")){title="Catch a thought";value="Keep a line";detail="Open your private notebook";}else if(a.equals("session")){title="Writing time";long remaining=Math.max(0,(d.optLong("sessionEndsAt",0)-System.currentTimeMillis())/60000);value=remaining>0?remaining+" min remaining":"Make room for 25 minutes";detail="Open your writing session";}else if(a.equals("library")){title="Your bookshelf";value=d.optInt("books",0)+" books";detail=d.optInt("chapters",0)+" drafted chapters";}else{title=d.optString("title","Your writing room");value=String.format(java.util.Locale.getDefault(),"%,d",d.optInt("wordCount",0));detail="Words on the page";}
 for(int id:ids){RemoteViews view=new RemoteViews(c.getPackageName(),R.layout.bookwiz_widget);view.setTextViewText(R.id.widget_title,title);view.setTextViewText(R.id.widget_value,value);view.setTextViewText(R.id.widget_detail,detail);view.setViewVisibility(R.id.widget_value,android.view.View.VISIBLE);view.setViewVisibility(R.id.widget_timer,android.view.View.GONE);long end=d.optLong("sessionEndsAt",0);if(a.equals("session")&&end>System.currentTimeMillis()){view.setViewVisibility(R.id.widget_value,android.view.View.GONE);view.setViewVisibility(R.id.widget_timer,android.view.View.VISIBLE);view.setBoolean(R.id.widget_timer,"setCountDown",true);view.setChronometer(R.id.widget_timer,android.os.SystemClock.elapsedRealtime()+end-System.currentTimeMillis(),"%s remaining",true);Intent tick=new Intent(c,getClass()).setAction(AppWidgetManager.ACTION_APPWIDGET_UPDATE).putExtra(AppWidgetManager.EXTRA_APPWIDGET_IDS,new int[]{id});PendingIntent alarm=PendingIntent.getBroadcast(c,id,tick,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((android.app.AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).set(android.app.AlarmManager.RTC,end,alarm);}Intent open=new Intent(c,MainActivity.class).putExtra("bookwiz-widget",a).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);view.setOnClickPendingIntent(R.id.widget_root,PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));manager.updateAppWidget(id,view);}}
 public static void refresh(Context c){for(Class<?> type:new Class<?>[]{CurrentBook.class,DailyGoal.class,QuickCapture.class,WritingTime.class,Bookshelf.class}){Intent i=new Intent(c,type).setAction(AppWidgetManager.ACTION_APPWIDGET_UPDATE);i.putExtra(AppWidgetManager.EXTRA_APPWIDGET_IDS,AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,type)));c.sendBroadcast(i);}}
}
